    .dialog-backdrop[data-open="true"] .dialog {
      transform: translateY(0) scale(1);
    }

    .dialog-content {
      padding: 28px;
    }

    .warning-icon {
      display: grid;
      width: 52px;
      height: 52px;
      margin-bottom: 18px;
      place-items: center;
      border-radius: 18px;
      color: #ffe4e6;
      background: rgba(225, 29, 72, 0.22);
      font-size: 1.6rem;
      font-weight: 900;
